/* Skins de flechas. Va en public/js/skins.js y se carga ANTES de game.js.
 *
 * Skins disponibles (las de imagen llevan la silueta incrustada, 256 px):
 *   classic   - las flechas de siempre (no se tocan)
 *   pug       - logo del pug
 *   paw       - huella con garras
 *   paw-solid - huella de oso
 * Cada columna rellena la imagen con su color. La elección se guarda en el equipo (localStorage 'ra_skin')
 * y se aplica a la siguiente partida.
 * API: RA.skins.get() -> id, RA.skins.set(id), RA.skins.def(id) -> { id, img, ready, rotate } | null, RA.skins.open()
 */
(function () {
  const STORE = 'ra_skin';
  const LIST = [
    { id: 'classic', name: 'Clásicas', desc: 'Las flechas de siempre.' },
    { id: 'pug', name: 'Pug', desc: 'El logo del pug en cada columna.', rotate: false, data: '' },
    { id: 'paw', name: 'Garra', desc: 'Huella con marcas de garras.', rotate: false, data: '' },
    { id: 'paw-solid', name: 'Huella', desc: 'Huella de oso con el color de cada columna.', rotate: false, data: '' },
  ];
  const ls = {
    get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
    set(k, v) { try { localStorage.setItem(k, v); } catch (e) { /* sin almacenamiento */ } },
  };

  // Imágenes incrustadas (no dependen de ninguna ruta): se cargan una vez al abrir la página
  const defs = {};
  for (const s of LIST) {
    if (!s.data) continue;
    const d = { id: s.id, rotate: !!s.rotate, ready: false, img: new Image() };
    d.img.onload = () => { d.ready = true; };
    d.img.src = 'data:image/png;base64,' + s.data;
    defs[s.id] = d;
  }

  let current = ls.get(STORE);
  if (!LIST.some((s) => s.id === current)) current = 'classic';
  const listeners = [];

  const api = {
    list: LIST.map((s) => ({ id: s.id, name: s.name, desc: s.desc })),
    def(id) { return defs[id] || null; },
    get() { return current; },
    set(id) {
      if (!LIST.some((s) => s.id === id)) return;
      current = id; ls.set(STORE, id);
      listeners.forEach((fn) => { try { fn(id); } catch (e) { /* */ } });
    },
    onChange(fn) { listeners.push(fn); },
    open: () => {},
  };

  // ------------------------------------------------------------- estilos (van dentro de este archivo)
  const CSS = `
#btn-skins{margin-left:0}
#btn-skins+#btn-fs-menu{margin-left:0}
#btn-keys[hidden]+#btn-skins{margin-left:auto}
.sk-overlay{position:fixed;inset:0;z-index:60;display:grid;place-items:center;padding:16px;background:rgba(5,6,18,.78)}
.sk-overlay[hidden]{display:none}
.sk-box{width:min(560px,100%);max-height:calc(100vh - 32px);overflow:auto;padding:22px;border-radius:18px;background:var(--panel-solid,#12142c);
  border:1px solid var(--line,rgba(140,160,255,.16));box-shadow:0 24px 70px rgba(0,0,0,.6)}
.sk-box h3{margin:0 0 6px;font-size:1.3rem}
.sk-intro{margin:0 0 14px;font-size:.9rem}
.sk-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.sk-card{display:flex;flex-direction:column;gap:8px;align-items:stretch;text-align:left;padding:12px;border-radius:14px;cursor:pointer;
  background:rgba(7,8,24,.75);border:2px solid var(--line,rgba(140,160,255,.16))}
.sk-card canvas{width:100%;height:auto;aspect-ratio:4/1.25;border-radius:10px;background:#05060f;display:block}
.sk-card strong{font-size:1rem}
.sk-card small{color:var(--muted,#8f95c2);font-weight:500}
.sk-card.on{border-color:var(--cyan,#4fd8ff);background:rgba(79,216,255,.1);box-shadow:0 0 0 3px rgba(79,216,255,.18)}
.sk-card.on strong::after{content:" ✓";color:var(--cyan,#4fd8ff)}
.sk-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:16px}
`;
  function injectCss() {
    if (document.getElementById('skins-css')) return;
    const st = document.createElement('style'); st.id = 'skins-css'; st.textContent = CSS;
    document.head.appendChild(st);
  }

  // ------------------------------------------------------------- diálogo
  function el(tag, cls, text) {
    const n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text !== undefined) n.textContent = text;
    return n;
  }

  let overlay = null, cards = [], lastFocus = null;
  function paintPreviews(tries) {
    let allOk = true;
    for (const c of cards) {
      const g = window.RA && window.RA.game;
      const ok = g && g.previewSkin ? g.previewSkin(c.canvas, c.id) : false;
      if (!ok) allOk = false;
    }
    if (!allOk && tries < 20) setTimeout(() => paintPreviews(tries + 1), 150); // las imágenes aún están cargando
  }
  function mark() { for (const c of cards) { const on = c.id === current; c.btn.classList.toggle('on', on); c.btn.setAttribute('aria-checked', String(on)); } }

  function build() {
    overlay = el('div', 'sk-overlay'); overlay.hidden = true;
    const box = el('div', 'sk-box');
    box.setAttribute('role', 'dialog'); box.setAttribute('aria-modal', 'true'); box.setAttribute('aria-labelledby', 'sk-title');
    const title = el('h3', '', 'Tipo de flecha'); title.id = 'sk-title';
    const intro = el('p', 'muted sk-intro', 'Elige cómo se ven las notas durante la partida. El cambio se aplica a la próxima canción.');
    const grid = el('div', 'sk-grid'); grid.setAttribute('role', 'radiogroup'); grid.setAttribute('aria-label', 'Tipo de flecha');
    for (const s of LIST) {
      const btn = el('button', 'sk-card'); btn.type = 'button'; btn.setAttribute('role', 'radio');
      const cv = document.createElement('canvas'); cv.width = 480; cv.height = 150;
      btn.append(cv, el('strong', '', s.name), el('small', '', s.desc));
      btn.addEventListener('click', () => { api.set(s.id); mark(); });
      grid.appendChild(btn); cards.push({ id: s.id, btn, canvas: cv });
    }
    const row = el('div', 'sk-actions');
    const bClose = el('button', 'primary', 'Listo'); bClose.type = 'button';
    row.appendChild(bClose);
    box.append(title, intro, grid, row); overlay.appendChild(box); document.body.appendChild(overlay);

    const close = () => { overlay.hidden = true; if (lastFocus && lastFocus.focus) lastFocus.focus(); };
    bClose.addEventListener('click', close);
    overlay.addEventListener('pointerdown', (e) => { if (e.target === overlay) close(); });
    document.addEventListener('keydown', (e) => { if (!overlay.hidden && e.code === 'Escape') { e.preventDefault(); close(); } }, true);
    api.open = () => { lastFocus = document.activeElement; mark(); overlay.hidden = false; paintPreviews(0); bClose.focus(); };
  }

  function init() {
    injectCss();
    const btn = document.getElementById('btn-skins');
    if (btn) btn.addEventListener('click', () => { if (!overlay) build(); api.open(); });
  }

  window.RA = window.RA || {};
  window.RA.skins = api;
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
